from pathlib import PurePosixPath
def accepted(name):
    path = PurePosixPath(name)
    if path.is_absolute():
        return False
    depth = 0
    for part in path.parts:
        if part == '..':
            depth -= 1
        elif part != '.':
            depth += 1
        if depth < 0:
            return False
    return True

